<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarCuentasParametros, guardarParametrosGenerales, obtenerParametrosGenerales } from '../services/parametrosGenerales'
import type { CuentaParametro, ParametroOption, ParametrosGenerales } from '../interfaces/parametrosGenerales.interface'
type SelectField={key:keyof ParametrosGenerales;label:string}
const comprobantes:SelectField[]=[{key:'tipo_comprobante_ape',label:'Comprobante de apertura'},{key:'tipo_comprobante_cierre',label:'Comprobante de cierre'},{key:'tipo_comprobante_acm',label:'Comprobante de A.C.M.'},{key:'tipo_comprobante_costos',label:'Comprobante de costos'},{key:'tipo_comprobante_ingresos',label:'Comprobante de ingresos'},{key:'tipo_comprobante_facturacion',label:'Comprobante de facturación'},{key:'tipo_comprobante_dist_cost',label:'Distribución de costos'},{key:'tipo_comprobante_cos_vent',label:'Costo de venta'}]
const documentos:SelectField[]=[{key:'tipo_documento_fa',label:'Factura'},{key:'tipo_documento_rs',label:'Recibo de servicios'},{key:'tipo_documento_nc',label:'Nota de crédito'},{key:'tipo_documento_nd',label:'Nota de débito'},{key:'tipo_documento_oc',label:'Orden de compra'},{key:'tipo_documento_os',label:'Orden de servicio'},{key:'tipo_documento_vi',label:'Viáticos'},{key:'tipo_documento_co',label:'Costos'},{key:'tipo_documento_dist_cost',label:'Distribución de costos'}]
const origenFields:SelectField[]=[{key:'origen_general',label:'General'},{key:'origen_rrhh',label:'Recursos Humanos'},{key:'origen_cost',label:'Costos'},{key:'origen_pres',label:'Presupuesto'},{key:'origen_pat',label:'Patrimonio'},{key:'origen_fin',label:'Finanzas'},{key:'origen_log',label:'Logística'}]
const cuentaFields:SelectField[]=[{key:'cuenta_contable_cuadre_acm',label:'Cuadre A.C.M.'},{key:'cuenta_contable_resul_util',label:'Resultado utilidad'},{key:'cuenta_contable_resul_perd',label:'Resultado pérdida'},{key:'cuenta_contable_cuenta_rei',label:'Cuenta REI'},{key:'cuenta_contable_cuenta_inv',label:'Cuenta inventario'},{key:'cuenta_contable_apertura',label:'Cuenta de apertura'}]
const blank=():ParametrosGenerales=>({id:null,tipo_comprobante_ape:null,tipo_comprobante_cierre:null,tipo_comprobante_acm:null,tipo_comprobante_costos:null,tipo_comprobante_ingresos:null,tipo_comprobante_facturacion:null,tipo_comprobante_dist_cost:null,tipo_comprobante_cos_vent:null,tipo_documento_fa:null,tipo_documento_rs:null,tipo_documento_nc:null,tipo_documento_nd:null,tipo_documento_oc:null,tipo_documento_os:null,tipo_documento_vi:null,tipo_documento_co:null,tipo_documento_dist_cost:null,origen_general:null,origen_rrhh:null,origen_cost:null,origen_pres:null,origen_pat:null,origen_fin:null,origen_log:null,cuenta_contable_cuadre_acm:null,cuenta_contable_resul_util:null,cuenta_contable_resul_perd:null,cuenta_contable_cuenta_rei:null,cuenta_contable_cuenta_inv:null,cuenta_contable_apertura:null,moneda_id:null,anio_base:new Date().getFullYear(),digitos_plan_contable:12,abc_calculo:'Especifica',porcentaje_igv:18,porcentaje_isc:0})
const form=reactive<ParametrosGenerales>(blank()),tiposComprobante=ref<ParametroOption[]>([]),tiposDocumento=ref<ParametroOption[]>([]),origenes=ref<ParametroOption[]>([]),monedas=ref<ParametroOption[]>([]),cuentaTextos=ref<Record<string,string>>({}),cuentas=ref<CuentaParametro[]>([]),target=ref<keyof ParametrosGenerales|null>(null),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),searchModal=ref(false)
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(){loading.value=true;try{const r=await obtenerParametrosGenerales();Object.assign(form,r.data);tiposComprobante.value=r.options.tipos_comprobante;tiposDocumento.value=r.options.tipos_documento;origenes.value=r.options.origenes;monedas.value=r.options.monedas;cuentaTextos.value=r.cuentas_texto??{}}catch(v){error.value=message(v)}finally{loading.value=false}}
function account(field:keyof ParametrosGenerales){target.value=field;query.value='';cuentas.value=[];searchModal.value=true}
async function search(){if(query.value.trim().length<3)return void(error.value='Ingrese al menos 3 caracteres.');try{cuentas.value=await buscarCuentasParametros(query.value.trim())}catch(v){error.value=message(v)}}
function choose(c:CuentaParametro){if(target.value){(form[target.value] as number|null)=c.id;cuentaTextos.value[String(target.value)]=`${c.cta_contable} - ${c.descripcion}`}searchModal.value=false}
async function save(){if(!form.moneda_id||form.anio_base<2000||form.anio_base>2100||form.digitos_plan_contable<1||form.digitos_plan_contable>20)return void(error.value='Revise moneda, año base y dígitos del plan contable.');if(form.porcentaje_igv<0||form.porcentaje_igv>100||form.porcentaje_isc<0||form.porcentaje_isc>100)return void(error.value='Los porcentajes deben estar entre 0 y 100.');saving.value=true;error.value='';try{Object.assign(form,await guardarParametrosGenerales(form));success.value='Parámetros generales guardados correctamente.'}catch(v){error.value=message(v)}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Parámetros generales</nav><header class="hero"><div class="mark">PG</div><div><small>MIA · CONTABILIDAD · CONFIGURACIÓN</small><h1>Parámetros generales</h1><p>Configuración indispensable para los procesos y automatizaciones contables.</p></div><button :disabled="saving" @click="save">Guardar parámetros</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><div v-if="loading" class="empty">Cargando parámetros…</div><main v-else><section class="card blue"><h2>Tipos de comprobante</h2><div class="grid"><label v-for="f in comprobantes" :key="f.key">{{f.label}}<select v-model="form[f.key]"><option :value="null">Seleccionar</option><option v-for="o in tiposComprobante" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label></div></section><section class="card green"><h2>Tipos de documento</h2><div class="grid"><label v-for="f in documentos" :key="f.key">{{f.label}}<select v-model="form[f.key]"><option :value="null">Seleccionar</option><option v-for="o in tiposDocumento" :key="o.id" :value="o.id">{{o.nombre}} {{o.diminutivo?`(${o.diminutivo})`:''}}</option></select></label></div></section><section class="card orange"><h2>Orígenes de comprobante</h2><div class="grid"><label v-for="f in origenFields" :key="f.key">{{f.label}}<select v-model="form[f.key]"><option :value="null">Seleccionar</option><option v-for="o in origenes" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label></div></section><section class="card violet"><h2>Cuentas contables especiales</h2><div class="grid"><label v-for="f in cuentaFields" :key="f.key">{{f.label}}<span class="account"><input :value="cuentaTextos[String(f.key)]||'Sin cuenta seleccionada'" readonly><button @click="account(f.key)">Buscar</button></span></label></div></section><section class="card cyan"><h2>Miscelánea</h2><div class="grid"><label>Moneda nacional *<select v-model="form.moneda_id"><option :value="null">Seleccionar</option><option v-for="o in monedas" :key="o.id" :value="o.id">{{o.nombre}} {{o.simbolo?`(${o.simbolo})`:''}}</option></select></label><label>Año base *<input v-model.number="form.anio_base" type="number" min="2000" max="2100"></label><label>Dígitos del plan<input v-model.number="form.digitos_plan_contable" type="number" min="1" max="20"></label><label>Cálculo ABC<select v-model="form.abc_calculo"><option value="Especifica">Específica</option><option value="Generica">Genérica</option></select></label><label>IGV %<input v-model.number="form.porcentaje_igv" type="number" min="0" max="100" step=".01"></label><label>ISC %<input v-model.number="form.porcentaje_isc" type="number" min="0" max="100" step=".01"></label></div></section><footer><button :disabled="saving" @click="save">Guardar parámetros</button></footer></main><div v-if="searchModal" class="backdrop" @mousedown.self="searchModal=false"><section class="dialog"><header><h2>Buscar cuenta contable</h2><button @click="searchModal=false">×</button></header><form @submit.prevent="search"><input v-model="query" placeholder="Código o descripción"><button>Buscar</button></form><div class="results"><button v-for="c in cuentas" :key="c.id" @click="choose(c)"><b>{{c.cta_contable}}</b><span>{{c.descripcion}}</span><small>{{c.naturaleza}}</small></button></div></section></div></div></template>
<style scoped>
.page{--a:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero button,main>footer button,.account button,.dialog button{margin-left:auto;padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.empty{padding:50px;text-align:center}.card{margin-top:12px;padding:16px;border-left:4px solid;border-radius:9px;background:#fff}.card h2{margin:0 0 13px;font-size:.72rem;text-transform:uppercase}.blue{border-color:#3b6da0}.green{border-color:#38a379}.orange{border-color:#d39138}.violet{border-color:#765a9e}.cyan{border-color:#2693a0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.card label{display:grid;gap:5px;color:#617078;font-size:.5rem}.card input,.card select,.dialog input{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.account{display:flex}.account button{margin-left:5px}.page main>footer{padding:16px;display:flex;justify-content:flex-end}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(680px,100%);padding:18px;border-radius:12px;background:#fff}.dialog header,.dialog form{display:flex;gap:7px}.dialog header h2{margin-right:auto}.dialog header button{margin-left:0;background:none;color:#59666c;font-size:1rem}.dialog form input{flex:1}.results{display:grid;max-height:330px;margin-top:10px;overflow:auto}.results button{margin:0 0 4px;display:grid;grid-template-columns:100px 1fr 70px;text-align:left;color:#35464e;background:#f1f5f7}.results small{text-align:right}@media(max-width:760px){.hero{flex-wrap:wrap}.hero button{margin-left:0}.grid{grid-template-columns:1fr 1fr}}@media(max-width:480px){.grid{grid-template-columns:1fr}}
</style>
